{
  "searches": [
    {
      "reason": "Build a trustworthy diagnostic foundation before interpreting context removal. Seek metamorphic tests that separate GRU padding or state-leakage defects from floating-point variation, localize divergence to recurrent states or readout, and translate score errors into top-10 stability bounds. Include checkpoint-to-predictor agreement; repeatability alone does not establish correctness.",
      "query": "GRU recurrent recommender metamorphic testing padding invariance batch invariance numerical precision explicit recurrence reference ranking stability error bounds 2024 2025 2026"
    },
    {
      "reason": "Develop an intervention-based context attribution probe instead of relying on aggregate training margins. Seek matched-target prefix deletion, recent-history deletion and order controls with fixed candidates, user-level uncertainty and training-derived popularity strata. These can distinguish dependence on older context from sensitivity to sequence length or order, without treating perturbations as proof of stale user intent. Use existing training prefixes without changing benchmark splits.",
      "query": "sequential recommendation diagnostic history intervention matched target prefix removal recency order sensitivity negative controls popularity confounding 2024 2025 2026"
    },
    {
      "reason": "Turn qualitative feedback into an auditable failure taxonomy: immediate choice, general or deferred interest, reported duplication or incompatibility, and unidentified content. Seek annotation agreement, abstention and contrastive ranking audits linking specific recent-purpose matches to GRU score changes. Validate title/description proxies against explicit judgments from the twenty users; report unsupported ownership or intent as unknown. Keep feedback audits separate from the fixed macro validation HR@10 and retain one model per category.",
      "query": "recommender diagnostic evaluation qualitative user feedback actionable intent complementarity redundancy incompatibility deferred interest abstention annotation reliability contrastive ranking audit 2024 2025 2026"
    }
  ]
}
